-- Checklist catalogue extension 1: the checklist wizard's 39 extra packs (390 questions) as product
-- templates, so the "Hazır listeler" library offers them and a wizard list copies them with their
-- verification method and help text instead of writing them as the expert's own questions.
--
-- Additive and staging-first, like checklist_catalog_v1. The base catalogue checklist-tr-2026-09-15-v1 is
-- not touched: the extension is its own catalogue version that names its base in the new
-- extends_catalog_version column. The library used to read only the newest catalogue version, which
-- would have hidden the 200 base templates; read_checklists_company_v3 now reads the newest base
-- together with its extensions. Everything else in that function is unchanged from
-- 20260921114500_checklist_catalog_completion (renamed in 20260921130000).
--
-- The extension rows stay professional_review_status 'pending' until a domain expert approves them
-- (see 20260921133000_checklist_catalog_professional_approval for the base catalogue). They make no
-- legal-compliance claim.
--
-- The seed block is generated from content/isg/checklist_wizard/source/packs.json by
-- scripts/isg/checklist_wizard/generate_extension_migration.mjs; do not edit it by hand.
BEGIN;
SET LOCAL lock_timeout='5s';

ALTER TABLE private_isg.checklist_catalogs
  ADD COLUMN IF NOT EXISTS extends_catalog_version text
    REFERENCES private_isg.checklist_catalogs(catalog_version) ON DELETE RESTRICT;
DO $$
BEGIN
  IF NOT EXISTS(SELECT 1 FROM pg_constraint WHERE conname='checklist_catalogs_extends_other_check') THEN
    ALTER TABLE private_isg.checklist_catalogs ADD CONSTRAINT checklist_catalogs_extends_other_check
      CHECK(extends_catalog_version IS NULL OR extends_catalog_version<>catalog_version);
  END IF;
END $$;

